    /**
     * @param array<string,array<string,mixed>> $defaults
     * @return array<string,array<string,mixed>>
     */
    public static function defaults(array $defaults): array
    {
        foreach (self::rows() as $key => $item) {
            $definition = [
                'label' => $item[0],
                'text' => $item[1],
                'group' => $item[3] ?? 'Organizer App',
            ];
            if (!empty($item[2])) $definition['required_tokens'] = array_values($item[2]);
            $defaults[$key] = $definition;
        }
        return $defaults;
    }

    public static function text(string $key, string $fallback): string
    {
        return function_exists('bg_str') ? \bg_str($key, $fallback) : $fallback;
    }

    /** Resolve editable text while retaining every registered dynamic placeholder. */
    public static function template(string $key, string $fallback): string
    {
        $text = self::text($key, $fallback);
        $row = self::rows()[$key] ?? null;
        foreach ((array) ($row[2] ?? []) as $token) {
            $marker = '{' . sanitize_key((string) $token) . '}';
            if ($marker !== '{}' && !str_contains($text, $marker)) $text = rtrim($text) . ' ' . $marker;
        }
        return $text;
    }

    /** @param array<string,scalar|null> $tokens */
    public static function format(string $key, string $fallback, array $tokens): string
    {
        if (function_exists('bg_str_format')) return \bg_str_format($key, $fallback, $tokens);
        $replace = [];
        foreach ($tokens as $token => $value) $replace['{' . $token . '}'] = (string) $value;
        return strtr(self::template($key, $fallback), $replace);
    }

    /** @return array<string,string> Client templates keyed without the module prefix. */
    public static function client(): array
    {
        $out = [];
        foreach (self::rows() as $key => $item) {
            $out[substr($key, strlen('organizer_app_'))] = self::template($key, $item[1]);
        }
        return $out;
    }
}
